import importlib.util, json, os, re, sys
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

WT = Path("/Users/gabe/Projects/monokl/.claude/worktrees/agent-aa1bb94557a4187f1")
spec = importlib.util.spec_from_file_location("agent_cost", WT / "scripts" / "agent-cost.py")
AC = importlib.util.module_from_spec(spec)
spec.loader.exec_module(AC)
RC = AC.RC
BASE = "/tmp/claude-501/mk/monokl-base"
RC.configure(BASE)
report_only = RC.report_only_repositories()
UNCAP = ["--min-score", "0", "--max-results", "1000000", "--max-tokens", "1000000000"]
ROW = AC.ROW


def get_rows():
    rows = [*AC.identifier_rows(BASE, None, 25), *AC.question_rows(None)]
    out = []
    for row in rows:
        expected = {}
        for file in row["files"]:
            found = AC.declaration_lines(row["path"], row["lang"], file, row["symbol"], row["member"])
            if found:
                expected[file] = found
        row["expected"] = expected
        row["sets"] = AC.set_names(row, report_only)
        # declared block per expected file
        row["declared"] = {}
        for file, decls in expected.items():
            spans = AC.monokl_spans(BASE, row["symbol"], row["path"], file)
            row["declared"][file] = AC.declared_block(spans, decls)
        out.append(row)
    return out


def parse(stdout):
    rows = []
    for line in stdout.splitlines():
        m = ROW.match(line)
        if not m:
            continue
        head, rank, score = line.rsplit(",", 2)
        kind = line.split(",", 4)[3]
        rows.append(dict(file=m.group(1).removeprefix("./"), l0=int(m.group(2)), l1=int(m.group(3)), kind=kind,
                         rank=int(rank), score=float(score), text=line))
    return rows


def run_one(binary, env, row, dump=False):
    import subprocess
    e = dict(os.environ)
    e.update(env)
    if dump:
        e["MK_DUMP"] = "1"
    r = subprocess.run([binary, "search", row["query"], ".", *UNCAP, "--snippet-lines", "1"], cwd=row["path"],
                       capture_output=True, text=True, env=e)
    rows = parse(r.stdout)
    dumps = {}
    if dump:
        for line in r.stderr.splitlines():
            if line.startswith("DUMP\t"):
                _, f, l0, l1, kind, name, bm, nb, tb, dl, avg, fin = line.split("\t")
                dumps[(f.removeprefix("./"), int(l0), int(l1))] = dict(name=name, bm25=float(bm), nb=float(nb), tb=float(tb),
                                                                     doclen=int(dl), avg=float(avg), final=float(fin))
    return rows, dumps


def evaluate(row, rows):
    exp = row["expected"]
    non_test = [r for r in rows if not RC.is_test_path(r["file"], row["lang"])]
    files = []
    for r in non_test:
        if r["file"] not in files:
            files.append(r["file"])
    file_rank = next((i for i, f in enumerate(files, 1) if f in exp), None)
    loose = strict = None
    for i, r in enumerate(rows, 1):
        if r["file"] in exp:
            decl_here = any(r["l0"] <= n <= r["l1"] for n, _ in exp[r["file"]])
            if decl_here and loose is None:
                loose = i
            if strict is None and row["declared"].get(r["file"]) == (r["l0"], r["l1"]):
                strict = i
    answerable = False
    for r in rows[:3]:
        shown = r["text"].translate(AC.BARE)
        if r["file"] in exp and any(r["l0"] <= n <= r["l1"] and AC.declaration_prefix(d) in shown for n, d in exp[r["file"]]):
            answerable = True
    return dict(file_rank=file_rank, loose=loose, strict=strict, answerable=answerable)


def run_variant(rows_meta, binary, env, dump=False, workers=6):
    def f(row):
        rows, dumps = run_one(binary, env, row, dump)
        ev = evaluate(row, rows)
        ev["top"] = [(r["file"], r["l0"], r["l1"], r["kind"], r["score"]) for r in rows[:3]]
        if dump:
            ev["rows"] = rows
            ev["dumps"] = dumps
        return ev
    with ThreadPoolExecutor(workers) as ex:
        return list(ex.map(f, rows_meta))


if __name__ == "__main__":
    import pickle
    meta = get_rows()
    pickle.dump(meta, open("/tmp/claude-501/mk/meta.pkl", "wb"))
    print(len(meta))

