import json, sys
d = json.load(open(sys.argv[1]))
info, res = d["info"], d["res"]
base = res.get("proto0") or res[list(res)[0]]


def top3(x):
    return bool(x["file_rank"] and x["file_rank"] <= 3)


def summary(r):
    qm = [(i, x) for i, x in zip(info, r) if i["kind"] != "identifier"]
    return dict(
        ans=sum(x["answerable"] for x in r),
        top3=sum(top3(x) for x in r),
        r1=sum(1 for i, x in qm if x["strict"] == 1),
        top3rows=sum(1 for i, x in qm if x["strict"] and x["strict"] <= 3),
        qm_ans=sum(1 for i, x in qm if x["answerable"]),
    )


print(f"{'variant':<24} ans/222 top3/222 | q+m(150): rank1 top3rows ans | lost(ans,top3,r1) gained(ans,top3,r1)")
for name, r in res.items():
    s = summary(r)
    lost = [0, 0, 0]
    gain = [0, 0, 0]
    det = []
    for i, b, x in zip(info, base, r):
        for k, (fb, fx) in enumerate([(b["answerable"], x["answerable"]), (top3(b), top3(x)),
                                      (b["strict"] == 1, x["strict"] == 1)]):
            if fb and not fx:
                lost[k] += 1
                det.append((k, i["repo"], i["query"], b["strict"], x["strict"]))
            if fx and not fb:
                gain[k] += 1
    print(f"{name:<24} {s['ans']:>7} {s['top3']:>8} | {s['r1']:>14} {s['top3rows']:>8} {s['qm_ans']:>4} | {tuple(lost)} {tuple(gain)}")
    if len(sys.argv) > 2 and name in sys.argv[2:]:
        for dd in det:
            print("      lost", ["ans", "top3", "r1"][dd[0]], dd[1:])
        for i, b, x in zip(info, base, r):
            if (x["strict"] == 1) and b["strict"] != 1 and i["kind"] != "identifier":
                print("      gained r1:", i["repo"], i["query"])

